'use strict';

// One identity check for copy-ready drafted replies, shared by the Emails to
// Action producer and the briefing card QC so the two never drift apart. It
// reads only the reply text, so producer and QC always reach the same answer.
//
// Always blocked: Amy, assistant, model and vendor names, and any statement
// that software wrote or helped write this reply ("as an AI", "I used AI to
// draft this note", "this was generated by AI"). "AI" as a business subject
// passes ("the AI platform", "AI-generated forecasts", "deploy an AI model"):
// Owner decision, Ed's "AI platform" reply is not an Amy leak.

const ALWAYS_BLOCKED_RE =
  /\b(?:amy|assistant|chatgpt|gpt|claude|openai|anthropic|language model|llm|chatbot|bot)\b/i;

// The lookahead ends the word without \b, which would not match after "a.i.".
const AI = String.raw`(?:ai|a\.i\.|artificial intelligence)(?![a-z])`;
const AI_RE = new RegExp(String.raw`\b${AI}`, 'i');

// Unambiguous disclosures, wherever they appear.
const DISCLOSURE_RE = new RegExp(
  [
    String.raw`\bas an? ${AI}`,
    String.raw`\b(?:written|drafted|composed|worded|polished) (?:by|with|using|via|through) (?:an? |the )?${AI}`,
    String.raw`\b(?:i|we)(?:'ve| have)? (?:used|use|asked|had|let|got) (?:an? |the )?${AI}(?: tools?)?(?: to)?(?: help(?: me| us)?)?(?: to)? (?:draft|write|compose|word|polish|prepare|answer|reply|respond)`,
  ].join('|'),
  'i',
);

// A sentence that names AI, an authorship verb, and this message itself.
const AUTHORSHIP_RE =
  /\b(?:draft(?:ed|s)?|wr(?:ote|ite|itten)|compos(?:ed|e)|generat(?:ed|e)|prepar(?:ed|e)|creat(?:ed|e)|help(?:ed)?|assist(?:ed)?|polish(?:ed)?|produc(?:ed|e))\b/i;
const THIS_MESSAGE_RE =
  /\b(?:this|the) (?:note|reply|response|email|message|draft|summary|text|letter|answer)\b|\bthis (?:is|was)\b|\b(?:my|our) (?:reply|response|note|email|message|draft|answer)\b|\b(?:wr(?:ote|ite)|draft(?:ed)?|compos(?:ed|e)|prepar(?:ed|e)|polish(?:ed)?|generat(?:ed|e)) this\b/i;

// Software that is not called AI ("drafted by a model", "software helped
// write this response"). These words are ordinary in business email, so they
// count only when they directly author the message (Codex 55f2c8823056).
const SOFTWARE = String.raw`(?:software|automation|(?:a|an|the|my|our) (?:model|tool|program|app|machine))`;
const SOFTWARE_AUTHOR_RE = new RegExp(
  [
    String.raw`\b(?:written|drafted|composed|generated|produced|created|prepared|polished|worded) (?:by|with|using|via|through) ${SOFTWARE}\b`,
    String.raw`\b${SOFTWARE} (?:helped (?:me |us )?(?:to )?)?(?:wrote|write|drafted|draft|composed|compose|generated|generate|prepared|prepare|polished|polish)\b`,
    String.raw`\b(?:i|we)(?:'ve| have)? (?:used|use|asked|had|let|got) ${SOFTWARE} to (?:help (?:me |us )?)?(?:draft|write|compose|word|polish|prepare|answer)\b`,
  ].join('|'),
  'i',
);

// Returns the offending text, or '' when the reply is clean.
function draftedReplyIdentityLeak(reply) {
  const text = String(reply || '');
  if (!text.trim()) return '';
  const blocked = text.match(ALWAYS_BLOCKED_RE);
  if (blocked) return blocked[0];
  const disclosure = text.match(DISCLOSURE_RE);
  if (disclosure) return disclosure[0];
  for (const sentence of text.split(/(?<=[.!?])\s+|\\n|\n/)) {
    if (!THIS_MESSAGE_RE.test(sentence)) continue;
    if (AI_RE.test(sentence) && AUTHORSHIP_RE.test(sentence)) return sentence.trim();
    if (SOFTWARE_AUTHOR_RE.test(sentence)) return sentence.trim();
  }
  return '';
}

module.exports = { draftedReplyIdentityLeak };
